// 2 - Check Name, Email, Phone and Message Arrived
// The chatbot snippet posts one JSON body per lead. Field names are mapped here once,
// so if the snippet sends fullName or tel instead, only this map changes.
const MAP = { name: ['name', 'fullName', 'full_name'], email: ['email', 'emailAddress'], phone: ['phone', 'tel', 'phoneNumber'], message: ['message', 'msg', 'question'] };
const REQUIRED = ['name', 'email', 'phone', 'message'];

return $input.all().map(({ json }) => {
  const b = json.body || {};
  const pick = (keys) => { for (const k of keys) { const v = b[k]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } return ''; };
  const lead = {};
  for (const f of REQUIRED) lead[f] = pick(MAP[f]);
  lead.email = lead.email.toLowerCase();

  const missing = REQUIRED.filter((f) => !lead[f]);
  const problems = [...missing];
  if (lead.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.email)) problems.push('email format');
  if (lead.phone && lead.phone.replace(/[^0-9]/g, '').length < 7) problems.push('phone too short');

  return { json: {
    ...lead,
    session_id: b.session_id || '',
    page_url: b.page_url || json.headers?.referer || '',
    preferred_time: b.preferred_time || '',
    captured_at: b.captured_at || new Date().toISOString(),
    received_at: new Date().toISOString(),
    passed: problems.length === 0,
    missing: problems.join(', '),
    raw_keys: Object.keys(b).join(', '),
  } };
});

